#!/bin/bash
# Builds LittleGuyBar.app into ~/Applications (menu bar only, no Dock icon).
set -e
cd "$(dirname "$0")"
APP=~/Applications/LittleGuyBar.app
mkdir -p "$APP/Contents/MacOS"
ROOT="$(cd ../.. && pwd)"
# Your board's address and ssh host live in littleguy.env (copy littleguy.env.example); they get baked in here.
[ -f "$ROOT/littleguy.env" ] || { echo "missing $ROOT/littleguy.env (copy littleguy.env.example)"; exit 1; }
set -a; . "$ROOT/littleguy.env"; set +a
cat > Settings.swift <<SWIFT
// Generated by build.sh from littleguy.env. Not in git.
import Foundation
let boardURL = URL(string: "$LITTLEGUY_BOARD_URL/api/status")!
let boardSSH = "$LITTLEGUY_BOARD_SSH"
let claudeLog = URL(fileURLWithPath: "$HOME/Library/Logs/LittleGuy/live-runs.log")  // what Claude runs, live (tools/show)
let orbPath = "${ORB:-/opt/homebrew/bin/orb}"   // talking to him: messages go into his room through the guard
let roomMachine = "${MACHINE:-lgroom}"
SWIFT
swiftc -O -parse-as-library -target arm64-apple-macos15 LittleGuyBar.swift Settings.swift -o "$APP/Contents/MacOS/LittleGuyBar"
cat > "$APP/Contents/Info.plist" <<'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>CFBundleIdentifier</key><string>ca.bymartins.littleguybar</string>
  <key>CFBundleName</key><string>Little Guy</string>
  <key>CFBundleExecutable</key><string>LittleGuyBar</string>
  <key>CFBundlePackageType</key><string>APPL</string>
  <key>CFBundleShortVersionString</key><string>1.0</string>
  <key>LSMinimumSystemVersion</key><string>15.0</string>
  <key>LSUIElement</key><true/>
  <key>NSLocalNetworkUsageDescription</key><string>Little Guy reads his status from the board on your home network.</string>
  <key>NSAppTransportSecurity</key><dict><key>NSAllowsLocalNetworking</key><true/></dict>
</dict></plist>
EOF
codesign --force --sign - "$APP"
echo "built $APP"
